window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-e048b9e392c6f248"]={"versions": [{"id": "FIG-e048b9e392c6f248", "releases": ["R23-11", "R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Use-Case-Diagramm (Anwendungsfalldiagramm) mit domänenspezifischen AUTOSAR-Adaptive-Stereotypen (<code>«aap...»</code>).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Adaptive Platform (AP), Dokument <em>AUTOSAR_AP_EXP_SWArchitecture</em>, Cluster <em>Platform Health Management (PHM)</em>.</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation der Beteiligungsverhältnisse beim Auftreten eines Überwachungsfehlers (Supervision Failure) im PHM. Das Diagramm definiert die funktionale Schnittstelle des Anwendungsfalls <em>Report Supervision Failure</em>, um erkannte Integritätsverletzungen an übergeordnete Kontroll- und Rückfallebenen weiterzuleiten (State Management zur Einleitung von Recovery-Aktionen und Watchdog zur Absicherung der Hardware-/ECU-Ebene).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Systemgrenzen (System Boundaries):</strong></li>\n<li><code>Adaptive Platform</code>: Äußerer Systemkontext der Laufzeitumgebung.</li>\n<li><code>Platform Health Management</code>: Kapselnder Subsystem-Kontext (Funktionaler Cluster), in dem der Use Case verortet ist.</li>\n<li><strong>Akteure (Actors):</strong></li>\n<li><code>Watchdog</code> (Qualifizierung: <code>(from Actors)</code>): Primärer externer oder plattformnaher Überwachungsakteur (z. B. HW-Watchdog bzw. Watchdog-Treiber/Daemon), der bei ausbleibendem Triggering den System-Reset forciert.</li>\n<li><strong>Anwendungsfall (Use Case):</strong></li>\n<li><code>«aapUseCase» Report Supervision Failure</code>: Spezifischer Anwendungsfall zur Signalisierung determinierter Fehlerzustände (Alive-, Deadline- oder Logical-Supervision-Verletzungen sowie Health-Channel-Meldungen).</li>\n<li><strong>Funktionale Cluster (Functional Clusters):</strong></li>\n<li><code>«aapFunctionalCluster» State Management</code> (Zusatzannotation: <code>daemon-based</code>): Zentraler System-Koordinator der Adaptive Platform, ausgeführt als eigener Daemon-Prozess, verantwortlich für State-Transitions, Degraded-Modes und Recovery-Entscheidungen.</li>\n<li><strong>Beziehungen:</strong></li>\n<li>Assoziation <code>Watchdog</code> $\\leftrightarrow$ <code>Report Supervision Failure</code> mit Stereotyp <code>«aapParticipates»</code>: Deklariert den Watchdog als involvierten Reaktions- oder Benachrichtigungspartner.</li>\n<li>Assoziation <code>State Management</code> $\\leftrightarrow$ <code>Report Supervision Failure</code> mit Stereotyp <code>«aapParticipates»</code>: Bindet das State Management als Empfänger der Fehlerbenachrichtigung zur Einleitung koordinierter Recovery-Maßnahmen ein.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Fehlerdetektion (PHM-intern):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Das PHM registriert eine Verletzung einer definierten Überwachungsregel einer <em>Supervised Entity</em> (z. B. verletztes Timing-Fenster bei <em>Deadline Supervision</em>, fehlerhafte Checkpoint-Reihenfolge bei <em>Logical Supervision</em> oder verpasster Heartbeat bei <em>Alive Supervision</em>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Auslöser (Trigger):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Übergang des lokalen oder globalen Supervision-Status in den Zustand <code>EXPIRED</code> bzw. <code>FAILED</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Meldung an State Management (asynchron / IPC):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>PHM signalisiert das Überwachungsereignis über plattforminternes IPC an den Daemon des <code>State Management</code>.</li>\n<li><strong>Reaktion SM:</strong> State Management evaluiert das Fehlerszenario anhand hinterlegter State-Management-Regeln und leitet zielgerichtete Recovery-Schritte ein (z. B. Prozessneustart via <em>Execution Management</em>, Deaktivierung von Funktionsgruppen, Übergang in einen <em>Degraded/Fallback Mode</em>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Interaktion mit dem Watchdog:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Je nach Ausprägung und Konfiguration:</li>\n<li><em>Passiver/Restriktiver Pfad:</em> PHM setzt das periodische Nachführen/Servicen des Watchdogs für die fehlerhafte Entität aus; bei kritischen Gesamtsystemfehlern wird das Watchdog-Triggern komplett unterdrückt, sodass der Hardware-Watchdog nach Ablauf der Timeout-Zeitspanne einen Hard-Reset erzwingt.</li>\n<li><em>Aktiver Pfad:</em> Direkte Deaktivierung oder Übergabe des Fehlerzustands an die Watchdog-Verwaltungslogik.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>PHM-Konfiguration (ARXML / Manifest):</strong></li>\n<li>Entwickler müssen für jede <code>SupervisedEntity</code> Recovery-Aktionen im PHM-Execution- bzw. Service-Instance-Manifest definieren. Die Weiterleitung an das State Management erfordert eine konsistente Modellierung der <code>PHMRecoveryNotification</code>-Schnittstellen und korrespondierender Action-Lists im State Management.</li>\n<li><strong>Architektonische Trennung (Separation of Concerns):</strong></li>\n<li>Das PHM führt Fehlerreaktionen nicht autonom-vollständig durch, sondern delegiert die Systemreaktion an <code>State Management</code>. Es ist als reiner Detektions- und Meldeknoten konzipiert.</li>\n<li>Entwickler dürfen Fehler-Recovery (z. B. Prozess-Neustarts, Graceful Shutdowns) nicht direkt in Applikationsprozessen abhandeln; dies muss über definierte Trigger an SM/EM erfolgen.</li>\n<li><strong>Daemon-Abhängigkeit:</strong></li>\n<li>Da <code>State Management</code> als <code>daemon-based</code> Cluster ausgelegt ist, erfolgt die Kommunikation über Inter-Process Communication (IPC). Bei vollständigem Hängen des Betriebssystems oder des IPC-Subsystems greift die zweite Linie (<code>Watchdog</code>) als autarker Notlauf-Pfad, um Deadlocks der Adaptive Platform deterministisch abzufangen.</li>\n</ul>"}, {"id": "FIG-4310a99fdb6e7fd1", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Use-Case-Diagramm (Anwendungsfalldiagramm) mit domänenspezifischen AUTOSAR-Adaptive-Stereotypen (<code>«aap...»</code>) und UML-Standardbeziehung (<code>«extend»</code>).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Adaptive Platform (AP), Dokument <em>AUTOSAR_AP_EXP_SWArchitecture</em>, Cluster <em>Platform Health Management (PHM)</em>.</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation der Beteiligungsverhältnisse und Abläufe beim Auftreten eines Überwachungsfehlers (Supervision Failure) im PHM. Das Diagramm definiert den primären Anwendungsfall <em>Report Supervision Failure</em> (Meldung an das State Management) sowie den abgeleiteten Anwendungsfall <em>Fire Watchdog Reaction</em> zur Ansteuerung des Watchdogs bei eskalierenden Fehlerzuständen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Systemgrenzen (System Boundaries):</strong></li>\n<li><code>Adaptive Platform</code>: Äußerer Systemkontext der Laufzeitumgebung.</li>\n<li><code>Platform Health Management</code>: Kapselnder Subsystem-Kontext (Funktionaler Cluster), in dem die beiden Use Cases verortet sind.</li>\n<li><strong>Akteure (Actors):</strong></li>\n<li><code>Watchdog</code> (Qualifizierung: <code>(from Actors)</code>): Primärer externer oder plattformnaher Überwachungsakteur (z. B. HW-Watchdog bzw. Watchdog-Treiber/Daemon), der bei ausbleibendem Triggering den System-Reset forciert.</li>\n<li><strong>Anwendungsfälle (Use Cases):</strong></li>\n<li><code>«aapUseCase» Report Supervision Failure</code>: Primärer Anwendungsfall zur Signalisierung determinierter Fehlerzustände an das State Management.</li>\n<li><code>«aapUseCase» Fire Watchdog Reaction</code>: Erweiternder Anwendungsfall zur gezielten Auslösung von Watchdog-Reaktionen.</li>\n<li><strong>Funktionale Cluster (Functional Clusters):</strong></li>\n<li><code>«aapFunctionalCluster» State Management</code> (Zusatzannotation: <code>daemon-based</code>): Zentraler System-Koordinator der Adaptive Platform, ausgeführt als eigener Daemon-Prozess.</li>\n<li><strong>Beziehungen:</strong></li>\n<li>Beziehung <code>Fire Watchdog Reaction</code> $\\xrightarrow{«extend»}$ <code>Report Supervision Failure</code>: UML-Erweiterungsbeziehung; deklariert die Watchdog-Reaktion als optionale/bedingte Erweiterung des primären Fehlerbehandlungsablaufs.</li>\n<li>Assoziation <code>Watchdog</code> $\\leftrightarrow$ <code>Fire Watchdog Reaction</code> mit Stereotyp <code>«aapParticipates»</code>: Bindet den Watchdog exklusiv an den Reaktions-Anwendungsfall an.</li>\n<li>Assoziation <code>State Management</code> $\\leftrightarrow$ <code>Report Supervision Failure</code> mit Stereotyp <code>«aapParticipates»</code>: Bindet das State Management an den primären Fehlermeldepfad an.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Fehlerdetektion (PHM-intern):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Das PHM registriert eine Verletzung einer definierten Überwachungsregel einer <em>Supervised Entity</em> (z. B. Alive-, Deadline- oder Logical-Supervision-Verletzung bzw. Health-Channel-Statusänderung).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Auslöser (Trigger):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Übergang des lokalen oder globalen Supervision-Status in den Zustand <code>EXPIRED</code> bzw. <code>FAILED</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Meldung an State Management (Basispfad <code>Report Supervision Failure</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>PHM signalisiert das Überwachungsereignis über plattforminternes IPC an den Daemon des <code>State Management</code>.</li>\n<li><strong>Reaktion SM:</strong> State Management evaluiert das Fehlerszenario anhand hinterlegter Regeln und leitet koordinierte Software-Recovery-Schritte ein (z. B. Neustart einzelner Prozesse via Execution Management oder Zustandswechsel in einen Safe State).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Bedingte Watchdog-Eskalation (Erweiterungspfad <code>Fire Watchdog Reaction</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ist eine entsprechende Eskalationsbedingung konfiguriert oder schlägt die softwareseitige Behebung fehl, greift die <code>«extend»</code>-Beziehung zu <code>Fire Watchdog Reaction</code>.</li>\n<li><strong>Interaktion mit dem Watchdog:</strong> PHM löst aktiv eine Watchdog-Aktion aus (z. B. Deaktivierung der Watchdog-Bedienung oder Forcieren eines Hard-Resets über den Watchdog-Akteur).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Spezifikationsstatus & Normative Einordnung:</strong> Das Diagramm aus <em>AUTOSAR_AP_EXP_SWArchitecture</em> dokumentiert die funktionale Verfeinerung in R25-11, bei der die Interaktion mit dem Watchdog aus dem Basis-Anwendungsfall herausgelöst und in einen eigenständigen Erweiterungs-Use-Case (<em>Fire Watchdog Reaction</em>) überführt wurde.</li>\n<li><strong>Architektonische Entkopplung:</strong> Die Einführung der <code>«extend»</code>-Beziehung trennt den regulären Fehlerbehandlungs- und Meldepfad an das State Management architektonisch sauber von der harten Hardware-Rückfallebene (Watchdog). Die Watchdog-Auslösung wird dadurch als bedingte Eskalationsstufe modelliert.</li>\n<li><strong>Entwickler- & Integrationshinweise:</strong></li>\n<li>Systemdesigner müssen in den PHM-Konfigurationsmodellen eindeutige Bedingungen definieren, wann eine Watchdog-Reaktion ausgelöst werden soll (Extension Points).</li>\n<li>State Management fungiert weiterhin als primärer Ansprechpartner für Graceful-Degradation und Recovery; Entwickler müssen sicherstellen, dass die Watchdog-Reaktion erst nach Ablauf etwaiger koordinierter Software-Rettungsfristen greift.</li>\n</ul>"}], "trans": [{"from": "FIG-e048b9e392c6f248", "to": "FIG-4310a99fdb6e7fd1", "fr": "R24-11", "tr": "R25-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><strong>Neuer Anwendungsfall:</strong> <code>«aapUseCase» Fire Watchdog Reaction</code> innerhalb von <code>Platform Health Management</code> ergänzt.</li>\n<li><strong>Neue Beziehung:</strong> Gerichtete <code>«extend»</code>-Beziehung von <code>Fire Watchdog Reaction</code> auf <code>Report Supervision Failure</code> eingefügt.</li>\n<li><strong>Geänderte Assoziation:</strong> Die <code>«aapParticipates»</code>-Assoziation des Akteurs <code>Watchdog</code> wurde von <code>Report Supervision Failure</code> entfernt und stattdessen an <code>Fire Watchdog Reaction</code> angebunden.</li>\n</ul>"}]};
